import { getGanguesLevelFromXp, GANGUES_ATTRS } from './ganguesCharacters.js'

export const GANGUES_PATHS = ['atacante', 'defensor', 'mistico']
export const GANGUES_AP_PER_XP = 10
export const GANGUES_INITIAL_PARTY_SIZE = 2
export const GANGUES_MAX_PARTY_SIZE = 6
export const GANGUES_ROSTER_LIMITS = { free: 2, elite: 2, primordial: 2 }

// ── Save slots: quantas gangues em paralelo por conta ──
// Cada save tem seu próprio nome, elenco e progresso no mapa — permite
// recrutar elencos diferentes sem perder o save anterior. Guest não salva
// na nuvem, então não tem conceito de save slot (joga só em memória).
export const GANGUES_SAVE_SLOT_LIMITS = { free: 1, elite: 2, primordial: 3 }
// BETA (Isaias, 27/09/2026): "deixa liberado três slots para todo mundo
// durante o beta". Enquanto for true, toda conta (free/elite/primordial) tem
// o teto máximo. No lançamento é só virar pra false — a regra 1/2/3 por plano
// já está pronta acima. Gangue criada a mais no beta NÃO some quando virar:
// o limite só impede fundar gangue nova, nunca apaga nem esconde save.
export const GANGUES_SAVE_SLOTS_BETA_LIBERADO = true
const GANGUES_SAVE_SLOT_MAX = Math.max(...Object.values(GANGUES_SAVE_SLOT_LIMITS))

export function getGanguesSaveSlotLimit(tier) {
  if (GANGUES_SAVE_SLOTS_BETA_LIBERADO) return GANGUES_SAVE_SLOT_MAX
  return GANGUES_SAVE_SLOT_LIMITS[tier] || GANGUES_SAVE_SLOT_LIMITS.free
}

// ── Modo história: teto de time de batalha + elenco que cresce por recrutamento ──
// Bairro é gangue contra gangue (bando inimigo sorteado, calibrado contra o
// total de pontos do seu time — ver data/ganguesEncontros.js) — o time que
// você leva pra briga cresce junto com o elenco recrutado, até um teto.
export const GANGUES_STORY_BATTLE_PARTY_MAX = 6
// Cada um dos 7 territórios dominado (chefe derrotado) libera 1 vaga nova no
// elenco, além do limite pago por tier — começa em 2, termina em 9.
export const GANGUES_STORY_ROSTER_BASE = GANGUES_INITIAL_PARTY_SIZE
export const GANGUES_STORY_ROSTER_TERRITORIOS_QUE_CONTAM = 7
export const GANGUES_STORY_ROSTER_MAX = 10

/** Quantos territórios já foram dominados (chefe derrotado)? */
export function contarTerritoriosDominados(storyProgress = {}) {
  return Object.values(storyProgress).filter(t => t?.chefe).length
}

// Multiplayer online libera quando PELO MENOS 3 fichas da gangue chegam no
// nível 99 (pedido do Isaias, 19/09/2026 — corrige a regra anterior, que só
// exigia 1 ficha). O online real ainda é fase futura — por ora isso só
// destrava o card em GanguesModes.
export const GANGUES_MULTIPLAYER_LEVEL = 99
export const GANGUES_MULTIPLAYER_MIN_FICHAS = 3
export function ganguesTemMultiplayer(roster = []) {
  return roster.filter(f => getGanguesLevelFromXp(f?.xp_total) >= GANGUES_MULTIPLAYER_LEVEL).length >= GANGUES_MULTIPLAYER_MIN_FICHAS
}

/** Vaga de elenco liberada pelo progresso da história — soma ao limite do tier, nunca substitui. */
export function getGanguesRosterLimitComHistoria(tier, storyProgress) {
  const dominados = Math.min(GANGUES_STORY_ROSTER_TERRITORIOS_QUE_CONTAM, contarTerritoriosDominados(storyProgress))
  const viaHistoria = Math.min(GANGUES_STORY_ROSTER_MAX, GANGUES_STORY_ROSTER_BASE + dominados)
  return Math.min(GANGUES_STORY_ROSTER_MAX, Math.max(getGanguesRosterLimit(tier), viaHistoria))
}

// Marco de reputação RECORRENTE: a cada 50 pontos acumulados (50, 100, 150,
// 200... sem teto), a gangue ganha automaticamente 1 item de "poder por 1
// uso" (ver ids 20/21/22 em ganguesItens.js) — cicla pelos 3 na ordem.
// `repMarcosCruzados(antes, depois)` devolve TODOS os marcos cruzados nesse
// ganho de rep (normalmente 1, mas pode ser mais de 1 se um ganho enorme
// pular vários de uma vez — quem chama concede o item de CADA um, mas só
// precisa exibir o modal do último). Pedido do Isaias (2026-09-14): "então tá
// errado, nada pode ser silencioso" — e depois (mesmo dia) pediu pra isso
// virar uma tela/modal de recompensa de verdade, não só um toast que passa.
export const GANGUES_REP_MARCO_INTERVALO = 50
export function repMarcosCruzados(antes, depois) {
  const marcos = []
  const primeiro = Math.floor(antes / GANGUES_REP_MARCO_INTERVALO) + 1
  const ultimo = Math.floor(depois / GANGUES_REP_MARCO_INTERVALO)
  for (let n = primeiro; n <= ultimo; n++) {
    const itemId = [20, 21, 22][(n - 1) % 3]
    marcos.push({ nivel: n, valor: n * GANGUES_REP_MARCO_INTERVALO, itemId })
  }
  return marcos
}

// ── Gates de reputação: conteúdo arriscado exige rep mínima ──
// Cada gate trava um conteúdo mais perigoso que o anterior: galpão do
// Carvão/Cão Louco < Clube da Luta. Pedido do Isaias (2026-09-14):
// território dominado já resolve recrutamento sozinho, então a reputação
// virou "risco liberado" em vez de "vaga extra de elenco".
// GANGUES_REP_GATE_EVENTO (removido 21/09/2026): existia pro antigo
// encontro aleatório de rua (sorteio por passo, sem pino no mapa). O
// encontro aleatório de hoje (perseguidor, engine/ganguesEncontroAleatorio.js)
// não usa gate de reputação — vem por tempo de jogo.
export const GANGUES_REP_GATE_GALPAO = 25
// (O gate do Clube da Luta mora no módulo dele: clube/ganguesClubeRegras.js.)

// Agiotagem (empréstimo em dinheiro do agiota) — pedido do Isaias, 21/09/2026:
// "você pega um empréstimo de até 100, mas paga 10 vezes mais, fica devendo
// 1000... a partir daí pode se endividar pelo dobro pra ganhar uma cura, até
// 10.000 — aí o agiota não cobra mais nada, te remenda de graça mas te joga
// pro Clube da Luta". Substitui de vez o fiado antigo (5×/10× por contagem).
// Escada: divida=0 → empréstimo (GANGUES_EMPRESTIMO_VALOR na mão, vira
// dívida ×MULT) → cada cura fiada DOBRA a dívida atual, até o teto. O agiota
// da Feira (Juro Alto) empresta mais (`poi.emprestimo`, 300) — mesmo ×MULT.
export const GANGUES_EMPRESTIMO_VALOR = 100
export const GANGUES_EMPRESTIMO_MULT = 10
export const GANGUES_EMPRESTIMO_TETO = 10000
// Prêmio de cada vitória completa no Clube da Luta, por bairro (GDD §9.7) —
// paga sempre, além de quitar a dívida.
export const GANGUES_CLUBE_PREMIO = { pista: 200, feira: 300, baixada: 450, vila: 650, morro: 900, alto: 1200, laje: 1600 }
export const clubePremioDe = territorioId => GANGUES_CLUBE_PREMIO[territorioId] ?? GANGUES_CLUBE_PREMIO.pista


export function getGanguesRosterLimit(tier) {
  return GANGUES_ROSTER_LIMITS[tier] || GANGUES_ROSTER_LIMITS.free
}

export const GANGUES_RESOURCE_RATES = {
  atacante: { pvPerR: 3, pmPerR: 3 },
  defensor: { pvPerR: 4, pmPerR: 2 },
  mistico: { pvPerR: 3, pmPerR: 4 }, // 26/09/2026: 2→3 — Mandingueiro com defesa normal, não de vidro
}

export function defaultGanguesProgression() {
  return { ap: 0, xp_unspent: 0, special_path: null, special_path_unlocked: false, special_levels: {}, selected_specials: [] }
}

export function getGanguesProgression(sheet = {}) {
  const source = sheet.attributes?.progression || sheet.progression || {}
  const specialLevels = Object.fromEntries(Object.entries(source.special_levels || {}).map(([id, level]) => [id, Math.max(0, Math.min(3, Number(level) || 0))]))
  const combatPath = sheet.combat_path || null
  const pathCandidate = source.special_path ? getGanguesSpecialPath(combatPath, source.special_path) : null
  const hasPurchasedPower = Boolean(pathCandidate?.specials.some(item => specialLevels[item.id] > 0))
  const pathUnlocked = Boolean(pathCandidate && (source.special_path_unlocked === true || hasPurchasedPower))
  const selectedPath = pathUnlocked ? pathCandidate.id : null
  const selected = Array.isArray(source.selected_specials) ? source.selected_specials.filter(id => specialLevels[id] > 0 && isGanguesSpecialAllowed(combatPath, selectedPath, id)).slice(0, 2) : []
  return { ...defaultGanguesProgression(), ...source, ap: Math.max(0, Number(source.ap) || 0), xp_unspent: Math.max(0, Number(source.xp_unspent) || 0), special_path: selectedPath, special_path_unlocked: pathUnlocked, special_levels: specialLevels, selected_specials: selected }
}

// Custo de AP por ponto de XP cresce com o nível do personagem (catálogo dos
// 30 personagens) — nível 1 custa 10 AP por XP, nível 2 custa 15, nível 3
// custa 20... +5 por nível. Sem isso, upar um personagem já avançado custava
// o mesmo AP que upar um recém-recrutado, o que ficava fácil demais (pedido
// do Isaias). Personagem "custom" (fora do catálogo, sem nível) continua no
// custo fixo de sempre.
export function ganguesApCostForLevel(level) {
  return 5 * (Math.max(1, Number(level) || 1) + 1)
}

export function ganguesXpMaxForSheet(sheet = {}) {
  if (sheet.character_type !== 'template') return GANGUES_AP_PER_XP
  return ganguesApCostForLevel(getGanguesLevelFromXp(sheet.xp_total))
}

// `levelCap`: teto de nível da área atual da história (nivelTetoDaHistoria em
// ganguesTerritorios.js). No teto o personagem para de subir e o AP não
// acumula — senão o grind guardava um banco de níveis pra despejar depois.
export function addGanguesAp(sheet, amount, levelCap = Infinity) {
  const progression = getGanguesProgression(sheet)
  let ap = progression.ap + Math.max(0, Number(amount) || 0)
  let earnedXp = 0
  if (sheet.character_type === 'template') {
    let xpTotal = Math.max(0, Number(sheet.xp_total) || 0)
    let cost = ganguesApCostForLevel(getGanguesLevelFromXp(xpTotal))
    while (ap >= cost && getGanguesLevelFromXp(xpTotal) < levelCap) {
      ap -= cost
      earnedXp += 1
      xpTotal += 1
      cost = ganguesApCostForLevel(getGanguesLevelFromXp(xpTotal))
    }
    if (getGanguesLevelFromXp(xpTotal) >= levelCap) ap = 0
  } else {
    earnedXp = Math.floor(ap / GANGUES_AP_PER_XP)
    ap = ap % GANGUES_AP_PER_XP
  }
  return { progression: { ...progression, ap, xp_unspent: progression.xp_unspent + earnedXp }, earnedXp }
}

export function toggleGanguesSpecial(sheet, specialId) {
  const progression = getGanguesProgression(sheet)
  if (!progression.special_levels[specialId] || !isGanguesSpecialAllowed(sheet.combat_path, progression.special_path, specialId)) return null
  const selected = progression.selected_specials.includes(specialId)
    ? progression.selected_specials.filter(id => id !== specialId)
    : progression.selected_specials.length < 2 ? [...progression.selected_specials, specialId] : progression.selected_specials
  return { attributes: { ...sheet.attributes, progression: { ...progression, selected_specials: selected } } }
}

// PV e PM são DOIS atributos compráveis independentes agora (era só um R
// alimentando os dois) — cada um multiplicado pela taxa do caminho, igual
// sempre foi (atacante 3/3, defensor 4/2, místico 2/4).
export function getGanguesResources(combatPath, pv = 0, pm = 0) {
  const rate = GANGUES_RESOURCE_RATES[combatPath] || { pvPerR: 0, pmPerR: 0 }
  return {
    pvMax: Math.max(0, Number(pv) || 0) * rate.pvPerR,
    pmMax: Math.max(0, Number(pm) || 0) * rate.pmPerR,
    ...rate,
  }
}

export function normalizeGanguesLoadout(sheet = {}) {
  const combatPath = GANGUES_PATHS.includes(sheet.combat_path) ? sheet.combat_path : null
  const source = sheet.attributes || {}

  return {
    combat_path: combatPath,
    // pv_atual/pm_atual: dano que persiste entre lutas repetíveis dentro da
    // mesma cena — sem isso, todo combatente voltava com a barra cheia a
    // cada reentrada, tirando o motivo de existir "descansar" ou gastar
    // grana. Só volta ao máximo via GanguesDescanso ou dominar o território
    // (ver restaurarPvPmTodos em useGanguesStore.js). Precisa ser copiado
    // manualmente porque esta função reconstrói `attributes` do zero.
    // equipment: 6 slots de equipamento por personagem (ver data/ganguesEquip.js) —
    // vive dentro de `attributes` (JSONB), precisa ser copiado manualmente porque
    // esta função reconstrói `attributes` do zero, igual pv_atual/pm_atual.
    attributes: { ...Object.fromEntries(GANGUES_ATTRS.map(attr => [attr, Math.max(0, Number(source[attr]) || 0)])), progression: getGanguesProgression({ combat_path: combatPath, attributes: source, progression: sheet.progression }), pv_atual: source.pv_atual, pm_atual: source.pm_atual, equipment: normalizeGanguesEquipment(source.equipment) },
    loadout_version: 2,
  }
}
import { getGanguesSpecialPath, isGanguesSpecialAllowed } from './ganguesSpecials.js'
import { normalizeGanguesEquipment } from './ganguesEquip.js'
